function makeCounters(n) {
  const fns = [];
  for (var i = 0; i < n; i++) {
    fns.push(() => i);
  }
  return fns.map((fn) => fn());
}

questions.correctCode:
function makeCounters(n) {
  const fns = [];
  for (let i = 0; i < n; i++) {
    fns.push(() => i);
  }
  return fns.map((fn) => fn());
}

questions.description:
`cloneAndMutate(user)` clones `user`, changes the CLONE's `address.city`, and returns the ORIGINAL `user`'s `address.city` — which should be completely unaffected by anything done to the clone.

```js
function cloneAndMutate(user) {
  const copy = { ...user };
  copy.address.city = 'Nowhere';
  return user.address.city;
}
```

The spread `{ ...user }` only copies the TOP level of the object. `copy.address` and `user.address` end up pointing at the exact same nested object, so mutating one mutates both.

Run checks:

- `cloneAndMutate({ name: 'A', address: { city: 'Boston' } })` should be `"Boston"`
- `cloneAndMutate({ name: 'B', address: { city: 'Reno' } })` should be `"Reno"`

Once both pass, submit the result of your fixed `cloneAndMutate({ name: 'C', address: { city: 'Austin' } })` as `CTF{result}` — exactly as returned, capitalization included.

questions.brokenCode:
function cloneAndMutate(user) {
  const copy = { ...user };
  copy.address.city = 'Nowhere';
  return user.address.city;
}

questions.correctCode:
function cloneAndMutate(user) {
  const copy = { ...user, address: { ...user.address } };
  copy.address.city = 'Nowhere';
  return user.address.city;
}

questions.description:
`flattenOnce(arr)` should flatten `arr` by exactly ONE level of nesting — equivalent to `arr.flat(1)` — leaving anything nested two or more levels deep still nested.

```js
function flattenOnce(arr) {
  return arr.flat(Infinity);
}
```

Run checks:

- `flattenOnce([1, [2, 3], [4, [5, 6]]])` should be `[1, 2, 3, 4, [5, 6]]`
- `flattenOnce([[1, 2], [3, [4]]])` should be `[1, 2, 3, [4]]`

Once both pass, run your fixed `flattenOnce([[1, [2]], [3, 4], [[5]]])` and submit the LENGTH of the resulting array as `CTF{n}`.

`runChallenge(factors)` should return each factor multiplied by `obj.value`.

```js
const obj = {
  value: 10,
  getValueTimes: function (factors) {
    return factors.map(function (f) {
      return this.value * f;
    });
  },
};

function runChallenge(factors) {
  return obj.getValueTimes(factors);
}
```

This one doesn't return a wrong number — it throws. Inside a plain `function (f) { ... }` passed to `.map`, `this` is not bound to `obj` at all.

Run checks:

- `runChallenge([1, 2, 3])` should be `[10, 20, 30]`
- `runChallenge([0.5, 2])` should be `[5, 20]`

Once both pass, submit your fixed `runChallenge([4, 5, 6])` joined by underscores as `CTF{a_b_c}`.

questions.brokenCode:
const obj = {
  value: 10,
  getValueTimes: function (factors) {
    return factors.map(function (f) {
      return this.value * f;
    });
  },
};

function runChallenge(factors) {
  return obj.getValueTimes(factors);
}

questions.correctCode:
const obj = {
  value: 10,
  getValueTimes: function (factors) {
    return factors.map((f) => {
      return this.value * f;
    });
  },
};

function runChallenge(factors) {
  return obj.getValueTimes(factors);
}
